SELECT id, symbol, interval_code, candle_open_time, generated_at, signal_mode, decision, original_decision, total_score, confidence_score, data_quality_valid, final_entry_allowed, primary_blocking_stage, selected_strategy, market_regime, entry_authority, entry_authority_max_position_percent, confluence_higher_interval, confluence_higher_decision, btc_context_status, latest_price, stop_loss, take_profit, risk_reward_ratio, atr_percent FROM trade_signal WHERE id IN (133249,128170,122431,121198,115669,115049) ORDER BY id;